bounded_host_request.command:
set -euo pipefail
python3 -B - <<'PY'
import urllib.request,sys
if bool(urllib.request.getproxies()):
 print("HOST_PROXY_CONFIG=YES")
else:
 print("HOST_PROXY_CONFIG=NO")
try:
 with urllib.request.urlopen('https://api.telegram.org',timeout=9) as r:
  if r.status<500:print("HOST_PYTHON_TELEGRAM_EGRESS=PASS")
  else:print("HOST_PYTHON_TELEGRAM_EGRESS=ERROR_STATUS")
except Exception:
 print("HOST_PYTHON_TELEGRAM_EGRESS=FAILED")
PY
docker run --rm --network host --pull never --read-only --cap-drop ALL --security-opt no-new-privileges:true --entrypoint node create-videobot:local-poll --input-type=module -e '
import {setDefaultResultOrder} from "node:dns";
setDefaultResultOrder("ipv4first");
try{
 const r=await fetch("https://api.telegram.org",{signal:AbortSignal.timeout(8000)});
 process.exitCode=r.status<500?0:70;
}catch(e){
 const c=String(e.cause?.code??e.code??"");
 const map={"ETIMEDOUT":80,"UND_ERR_CONNECT_TIMEOUT":81,"ENETUNREACH":82,"ENOTFOUND":83,"ECONNRESET":84,"ERR_TLS_CERT_ALTNAME_INVALID":85,"EAI_AGAIN":86,"ECONNREFUSED":87};
 process.exitCode=map[c]??88;
}'
